import { memoryAdapter } from '../src/adapters/memory.js';
import { createJobs } from '../src/index.js';

const jobs = createJobs({ adapter: memoryAdapter() });

await jobs.worker<{ to: string }>('email.welcome', async ({ to }, ctx) => {
  console.log(`sending welcome email to ${to} (attempt ${ctx.attempt}/${ctx.maxAttempts})`);
});
await jobs.enqueue('email.welcome', { to: 'ada@example.com' }, { idempotencyKey: 'welcome:ada' });
await new Promise((r) => setTimeout(r, 50));
await jobs.stop();
